import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import PerformanceChart from '../components/PerformanceChart';
import AIInsightCard from '../components/AIInsightCard';
import './AthleteProfile.css';

export default function AthleteProfile() {
  const { id } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [athlete, setAthlete] = useState(null);
  const [performances, setPerformances] = useState([]);
  const [aiAnalysis, setAiAnalysis] = useState(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [activeChartTab, setActiveChartTab] = useState('jumpHeight');
  const [injuries, setInjuries] = useState([]);
  const [injuryRisk, setInjuryRisk] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [aRes, pRes, injRes] = await Promise.all([
          axios.get(`/api/athletes/${id}`),
          axios.get(`/api/athletes/${id}/performance`),
          axios.get(`/api/athletes/${id}/injuries`).catch(() => ({ data: [] })),
        ]);
        setAthlete(aRes.data);
        setInjuries(injRes.data);

        // Load injury risk
        try {
          const riskRes = await axios.get(`/api/athletes/${id}/injury-risk`);
          setInjuryRisk(riskRes.data);
        } catch (e) { /* ignore */ }
        setPerformances(pRes.data);

        // Auto-load AI analysis if performances exist
        if (pRes.data.length > 0) {
          try {
            const aiRes = await axios.get(`/api/athletes/${id}/ai-analysis`);
            setAiAnalysis(aiRes.data);
          } catch (e) {
            console.error('AI analysis failed:', e);
          }
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [id]);

  const handleDelete = async () => {
    if (!window.confirm('Delete this athlete profile? This action cannot be undone.')) return;
    try {
      await axios.delete(`/api/athletes/${id}`);
      navigate('/athletes');
    } catch (err) {
      alert(err.response?.data?.error || 'Delete failed');
    }
  };

  const refreshAI = async () => {
    setAiLoading(true);
    try {
      const res = await axios.get(`/api/athletes/${id}/ai-analysis`);
      setAiAnalysis(res.data);
    } catch (err) {
      console.error('AI analysis failed:', err);
    } finally {
      setAiLoading(false);
    }
  };

  if (loading) return <div className="spinner" />;
  if (!athlete) return <div className="page"><p>Athlete not found.</p></div>;

  const best = performances.reduce((acc, p) => ({
    jumpHeight: Math.max(acc.jumpHeight || 0, p.jumpHeight || 0),
    jumpLength: Math.max(acc.jumpLength || 0, p.jumpLength || 0),
    runningSpeed: Math.max(acc.runningSpeed || 0, p.runningSpeed || 0),
  }), {});

  const chartMetrics = [
    { key: 'jumpHeight', label: 'Jump Height', unit: 'cm', color: '#1D9E75' },
    { key: 'jumpLength', label: 'Jump Length', unit: 'm', color: '#EF9F27' },
    { key: 'runningSpeed', label: 'Sprint Speed', unit: 'km/h', color: '#9333EA' },
  ];

  return (
    <div className="page">
      <Link to="/athletes" className="back-link">← Back to Athletes</Link>

      <div className="profile-layout">
        {/* Sidebar */}
        <div className="profile-sidebar">
          <div className="profile-avatar-wrap">
            <div className="profile-avatar">
              {athlete.profileImage
                ? <img src={athlete.profileImage} alt={athlete.name} />
                : <span>{athlete.name?.charAt(0)}</span>}
            </div>
            {aiAnalysis && aiAnalysis.overallScore > 0 && (
              <div className="profile-ai-badge" style={{ background: aiAnalysis.potential?.color || '#1D9E75' }}>
                {aiAnalysis.potential?.emoji} {aiAnalysis.overallScore}
              </div>
            )}
          </div>

          <h2>{athlete.name}</h2>

          <div className="profile-badges">
            {athlete.isRural && <span className="badge badge-green">🌾 Rural Athlete</span>}
            {aiAnalysis?.potential && (
              <span className="badge badge-gold">{aiAnalysis.potential.emoji} {aiAnalysis.potential.level}</span>
            )}
          </div>

          <div className="profile-details">
            {athlete.age && <div className="pd-item"><span className="pd-icon">🎂</span> Age {athlete.age}</div>}
            {(athlete.city || athlete.state) && (
              <div className="pd-item"><span className="pd-icon">📍</span> {[athlete.city, athlete.state].filter(Boolean).join(', ')}</div>
            )}
            {athlete.phone && <div className="pd-item"><span className="pd-icon">📞</span> {athlete.phone}</div>}
            {athlete.email && <div className="pd-item"><span className="pd-icon">✉️</span> {athlete.email}</div>}
          </div>

          {athlete.sports?.length > 0 && (
            <div className="profile-sports">
              {athlete.sports.map((s, i) => <span key={i} className="badge badge-muted">{s}</span>)}
            </div>
          )}

          {/* Injury Risk Indicator */}
          {injuryRisk && (
            <Link to={`/athletes/${id}/injuries`} className="profile-injury-risk">
              <div className="pir-header">
                <span>{injuryRisk.riskLevel?.emoji}</span>
                <strong style={{ color: injuryRisk.riskLevel?.color }}>{injuryRisk.riskLevel?.level} Risk</strong>
              </div>
              <div className="pir-stats">
                <span>{injuryRisk.activeInjuries} active</span>
                <span>•</span>
                <span>{injuryRisk.totalInjuries} total</span>
              </div>
              <span className="pir-link">View Injury Tracker →</span>
            </Link>
          )}

          {user && (
            <div className="profile-actions">
              <Link to={`/athletes/${id}/add-performance`} className="btn btn-primary btn-sm" style={{ width: '100%' }}>
                + Add Performance
              </Link>
              <Link to={`/athletes/${id}/injuries`} className="btn btn-secondary btn-sm" style={{ width: '100%' }}>
                🏥 Injury Tracker
              </Link>
              <button className="btn btn-danger btn-sm" onClick={handleDelete} style={{ width: '100%' }}>
                Delete Profile
              </button>
            </div>
          )}
        </div>

        {/* Main Content */}
        <div className="profile-main">
          {/* Bio */}
          {athlete.bio && (
            <div className="card profile-card" style={{ marginBottom: '1.25rem' }}>
              <div className="section-title-sm">About</div>
              <p style={{ color: 'rgba(240,237,230,0.6)', fontSize: '0.9rem', lineHeight: 1.75 }}>{athlete.bio}</p>
            </div>
          )}

          {/* Best Stats */}
          {performances.length > 0 && (
            <div className="card profile-card" style={{ marginBottom: '1.25rem' }}>
              <div className="section-title-sm">Best Performance</div>
              <div className="stats-row">
                {best.jumpHeight > 0 && (
                  <div className="stat-box">
                    <div className="stat-icon">⬆️</div>
                    <div className="stat-val">{best.jumpHeight}<span>cm</span></div>
                    <div className="stat-key">Jump Height</div>
                  </div>
                )}
                {best.jumpLength > 0 && (
                  <div className="stat-box">
                    <div className="stat-icon">↗️</div>
                    <div className="stat-val">{best.jumpLength}<span>m</span></div>
                    <div className="stat-key">Jump Length</div>
                  </div>
                )}
                {best.runningSpeed > 0 && (
                  <div className="stat-box">
                    <div className="stat-icon">⚡</div>
                    <div className="stat-val">{best.runningSpeed}<span>km/h</span></div>
                    <div className="stat-key">Top Speed</div>
                  </div>
                )}
                <div className="stat-box">
                  <div className="stat-icon">📊</div>
                  <div className="stat-val">{performances.length}</div>
                  <div className="stat-key">Sessions</div>
                </div>
              </div>
            </div>
          )}

          {/* Performance Charts */}
          {performances.length >= 2 && (
            <div className="card profile-card" style={{ marginBottom: '1.25rem' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                <div className="section-title-sm" style={{ marginBottom: 0 }}>Performance Trends</div>
                <div className="chart-tabs">
                  {chartMetrics.map(m => (
                    <button
                      key={m.key}
                      className={`chart-tab ${activeChartTab === m.key ? 'active' : ''}`}
                      onClick={() => setActiveChartTab(m.key)}
                    >
                      {m.label}
                    </button>
                  ))}
                </div>
              </div>
              {chartMetrics.map(m => (
                activeChartTab === m.key && (
                  <PerformanceChart
                    key={m.key}
                    performances={performances}
                    metric={m.key}
                    label={m.label}
                    unit={m.unit}
                    color={m.color}
                  />
                )
              ))}
            </div>
          )}

          {/* AI Analysis */}
          <div style={{ marginBottom: '1.25rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
              <div className="section-title-sm" style={{ marginBottom: 0 }}>🤖 AI Performance Intelligence</div>
              {performances.length > 0 && (
                <button className="btn btn-secondary btn-sm" onClick={refreshAI} disabled={aiLoading}>
                  {aiLoading ? 'Analyzing…' : '↻ Refresh Analysis'}
                </button>
              )}
            </div>
            {aiLoading ? (
              <div className="card" style={{ padding: '3rem', textAlign: 'center' }}>
                <div className="spinner" style={{ margin: '0 auto 1rem' }} />
                <p style={{ color: 'var(--text-muted)', fontSize: '0.88rem' }}>Running AI analysis on {performances.length} data points…</p>
              </div>
            ) : (
              <AIInsightCard analysis={aiAnalysis || { error: 'No performance data available.', overallScore: 0, potential: { level: 'Unknown', emoji: '❓', color: '#888', description: 'Add performances to unlock AI analysis.' }, recommendations: [{ category: 'Get Started', icon: '🚀', priority: 'high', text: 'Log your first performance to unlock AI-powered insights.' }] }} athleteName={athlete.name} />
            )}
          </div>

          {/* Injury Summary */}
          {injuries.length > 0 && (
            <div className="card profile-card" style={{ marginBottom: '1.25rem' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                <div className="section-title-sm" style={{ marginBottom: 0 }}>🏥 Recent Injuries</div>
                <Link to={`/athletes/${id}/injuries`} className="btn btn-secondary btn-sm">View All →</Link>
              </div>
              <div className="injury-summary-list">
                {injuries.slice(0, 3).map(inj => (
                  <div key={inj._id} className="injury-summary-item">
                    <span className="isi-icon">
                      {inj.recoveryStatus === 'active' ? '🔴' : inj.recoveryStatus === 'recovering' ? '🟡' : '🟢'}
                    </span>
                    <div className="isi-info">
                      <strong>{inj.type} — {inj.bodyPart}</strong>
                      <span>{new Date(inj.dateOccurred).toLocaleDateString()}</span>
                    </div>
                    <span className={`badge badge-${inj.severity === 'severe' ? 'danger' : inj.severity === 'moderate' ? 'amber' : 'green'}`}>
                      {inj.severity}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Performance History */}
          <div className="card profile-card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <div className="section-title-sm" style={{ marginBottom: 0 }}>Performance History</div>
              {user && <Link to={`/athletes/${id}/add-performance`} className="btn btn-secondary btn-sm">+ Add</Link>}
            </div>
            {performances.length === 0 ? (
              <p style={{ color: 'var(--text-faint)', fontSize: '0.88rem' }}>No performances logged yet.</p>
            ) : (
              <div className="perf-list stagger-children">
                {performances.map(p => (
                  <div key={p._id} className="perf-item">
                    <div className="perf-date">
                      {new Date(p.recordedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}
                    </div>
                    <div className="perf-metrics">
                      {p.jumpHeight && <span className="pm-chip">⬆️ {p.jumpHeight} cm</span>}
                      {p.jumpLength && <span className="pm-chip">↗️ {p.jumpLength} m</span>}
                      {p.runningDistance && p.runningTime && <span className="pm-chip">🏃 {p.runningDistance}m in {p.runningTime}s</span>}
                      {p.runningSpeed && <span className="pm-chip">⚡ {p.runningSpeed} km/h</span>}
                      {p.sport && <span className="badge badge-muted">{p.sport}</span>}
                    </div>
                    {p.notes && <p className="perf-notes">{p.notes}</p>}
                    {p.videoUrl && (
                      <a href={p.videoUrl} target="_blank" rel="noopener noreferrer" className="btn btn-secondary btn-sm" style={{ marginTop: '0.5rem' }}>
                        ▶ Watch Video
                      </a>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
